/// Given an action that failed to execute because of lost inputs which were generated by other
/// actions, finds the actions which generated them and the set of Skyframe nodes which must be
/// rewound in order to recreate the lost inputs.
///
/// PORT: Java holds the `SkyframeActionExecutor`; here the executor holds the strategy and
/// passes itself to the methods that need it. `cachingDependenciesSupplier` (remote analysis
/// caching) is not ported: `allowSkyframeRestarts()` is false, as in Bazel without a remote
/// analysis cache.
// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:90 ActionRewindStrategy
#[derive(Default)]
pub struct ActionRewindStrategy {
    /// Java: `Map<SkyKey, Multiset<LostInputRecord>>`.
    current_build_lost_input_records: Mutex<HashMap<SkyKey, HashMap<LostInputRecord, usize>>>,
    lost_inputs_count: AtomicUsize,
    lost_outputs_count: AtomicUsize,
    same_action_lost_inputs_count: AtomicUsize,
    same_top_level_key_lost_outputs_count: AtomicUsize,
    rewind_event_samples: Mutex<Vec<ActionRewindEvent>>,
    rewind_event_sample_counter: AtomicUsize,
}

/// The result of rewind planning.
// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:121 ActionRewindStrategy.RewindPlanResult
pub struct RewindPlanResult {
    /// `None` if there were missing dependencies.
    reset: Option<Reset>,
}

impl RewindPlanResult {
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:130 RewindPlanResult.toNullIfMissingDependenciesElseReset
    pub fn to_null_if_missing_dependencies_else_reset(self) -> Option<Reset> {
        self.reset
    }
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1066 ActionRewindStrategy.LostInputRecord
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct LostInputRecord {
    lost_input_digest: String,
    lost_input_path: String,
}

/// `ActionAndLookupDataOrTemplate`: an action (with its key) newly added to the rewind graph,
/// or an action template.
// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1073 ActionRewindStrategy.ActionAndLookupDataOrTemplate
#[derive(Clone)]
enum ActionAndLookupDataOrTemplate {
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1085 ActionRewindStrategy.ActionAndLookupData
    ActionAndLookupData(ActionLookupData, ActionRef),
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1078 ActionRewindStrategy.TemplateWrapper
    TemplateWrapper(ActionRef),
}

impl ActionAndLookupDataOrTemplate {
    fn action_analysis_metadata(&self) -> &ActionRef {
        match self {
            ActionAndLookupDataOrTemplate::ActionAndLookupData(_, action) => action,
            ActionAndLookupDataOrTemplate::TemplateWrapper(template) => template,
        }
    }
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:782 ActionRewindStrategy.CheckActionsStatus
#[derive(PartialEq, Eq)]
enum CheckActionsStatus {
    MissingDependencies,
    Success,
}

/// `SetMultimap<ActionInput, Artifact>` (a `HashMultimap`), keyed by exec path.
#[derive(Default)]
struct Owners {
    map: IndexMap<ActionInputRef, IndexSet<Artifact>>,
}

impl Owners {
    fn put(&mut self, key: ActionInputRef, value: Artifact) {
        self.map.entry(key).or_default().insert(value);
    }

    fn get(&self, key: &ActionInputRef) -> Vec<Artifact> {
        self.map
            .get(key)
            .map(|s| s.iter().cloned().collect())
            .unwrap_or_default()
    }
}

impl fmt::Debug for Owners {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Guava's Multimap.toString: {k=[v1, v2], ...}.
        f.write_str("{")?;
        for (i, (k, vs)) in self.map.iter().enumerate() {
            if i > 0 {
                f.write_str(", ")?;
            }
            write!(f, "{}=[", action_input_to_string(k))?;
            for (j, v) in vs.iter().enumerate() {
                if j > 0 {
                    f.write_str(", ")?;
                }
                write!(f, "{v}")?;
            }
            f.write_str("]")?;
        }
        f.write_str("}")
    }
}

/// `ActionInput.toString()`: `Artifact.toString()` for an artifact.
fn action_input_to_string(input: &ActionInputRef) -> String {
    match as_blaze_artifact(input) {
        Some(artifact) => artifact.to_string(),
        None => format!("{input:?}"),
    }
}

impl ActionRewindStrategy {
    pub fn new() -> ActionRewindStrategy {
        ActionRewindStrategy::default()
    }

    /// Returns a [`RewindPlanResult`] specifying the Skyframe nodes to rewind to recreate the
    /// lost inputs of `failed_action`.
    ///
    /// The returned [`RewindPlanResult`] always holds a [`Reset`] (`allowSkyframeRestarts()` is
    /// false).
    ///
    /// Also prepares the [`SkyframeActionExecutor`] for the rewind plan and emits an
    /// [`ActionRewoundEvent`] if necessary.
    ///
    /// Fails with an [`ActionRewindException`] if rewinding is disabled, or if any lost inputs
    /// have been seen by `failed_key` as lost before too many times. `Ok(Err(..))` carries an
    /// interrupt or a dependency error from the Skyframe lookups.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:229 ActionRewindStrategy.prepareRewindPlanForLostInputs
    pub fn prepare_rewind_plan_for_lost_inputs(
        &self,
        executor: &SkyframeActionExecutor,
        seam: &dyn AnalysisSeam,
        failed_key: &ActionLookupData,
        failed_action: &ActionRef,
        failed_action_deps: &IndexSet<SkyKey>,
        lost_inputs_by_digest: &LostArtifacts,
        action_started_event_already_emitted: bool,
        metadata_provider: &ActionInputMetadata,
        env: &mut Environment<'_>,
        action_start_time: Instant,
    ) -> Result<Result<RewindPlanResult, ComputeError>, ActionRewindException> {
        self.check_rewinding_enabled(executor, lost_inputs_by_digest)?;

        let lost_input_records = create_lost_input_records(lost_inputs_by_digest);

        let lost_inputs: Vec<ActionInputRef> = lost_inputs_by_digest
            .entries()
            .into_iter()
            .map(|(_, input)| input.clone())
            .collect();
        let owners = calculate_lost_input_owners(&lost_inputs, metadata_provider);

        let mut deps_to_rewind: Vec<ActionRef> = vec![];
        let failed_sky_key = SkyKey::new(ActionExecutionKey(failed_key.clone()));
        let rewind_plan_result = {
            let _c = Profiler::instance().profile(
                ProfilerTask::ACTION_REWINDING,
                &format!(
                    "Preparing rewind plan for {} lost inputs of {}",
                    lost_input_records.len(),
                    failed_action.pretty_print()
                ),
            );
            match self.prepare_rewind_plan(
                seam,
                &failed_sky_key,
                Some((failed_key, failed_action)),
                failed_action_deps,
                &lost_inputs,
                &owners,
                env,
                &mut deps_to_rewind,
            ) {
                Ok(r) => r,
                Err(e) => return Ok(Err(e)),
            }
        };
        let Some(rewind_plan) = &rewind_plan_result.reset else {
            // Skips steps that manipulate persistent state, structures retained by this class and
            // information tracked by SkyframeActionExecutor, if a restart is needed.
            //
            // This includes counting if an input has been lost too many times.
            return Ok(Ok(rewind_plan_result));
        };

        self.check_if_action_lost_input_too_many_times(
            executor,
            failed_key,
            failed_action,
            &lost_input_records,
            lost_inputs_by_digest,
        )?;

        if self.should_record_rewind_event_sample() {
            self.rewind_event_samples
                .lock()
                .push(create_lost_input_rewind_event(
                    failed_action,
                    rewind_plan,
                    &lost_input_records,
                ));
        }

        if action_started_event_already_emitted {
            env.listener().post(Arc::new(ActionRewoundEvent {
                relative_action_start_time: action_start_time,
                relative_action_finish_time: Instant::now(),
                failed_rewound_action: failed_action.clone(),
            }));
        }
        executor.prepare_for_rewinding(
            failed_key,
            failed_action,
            &deps_to_rewind,
            /* lost_own_outputs= */
            lost_inputs
                .iter()
                .any(|lost_input| is_output_of(failed_key, lost_input)),
        );

        Ok(Ok(rewind_plan_result))
    }

    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:307 ActionRewindStrategy.checkRewindingEnabled
    fn check_rewinding_enabled(
        &self,
        executor: &SkyframeActionExecutor,
        lost_artifacts: &LostArtifacts,
    ) -> Result<(), ActionRewindException> {
        if executor.rewinding_enabled() {
            // Action rewinding takes precedence over whole-invocation retries when both are
            // enabled. Remote execution skips cache lookup for rewound actions without tracking
            // lost digests. Other transient cache errors, including evicted repository files read
            // during loading, can still trigger invocation retries in BlazeCommandDispatcher
            // without passing here.
            return Ok(());
        }
        // PORT: the executor answers checkRewindingEnabled without rewinding itself (see
        // `SkyframeActionExecutor::handle_lost_inputs`, which posts the LostInputsEvent and builds
        // the FallbackToBuildRewindingException / GenericActionRewindException); this method is
        // reached only with rewinding enabled. (Java's `LostType` only picks the description and
        // failure code of the disabled case.)
        unreachable!(
            "checkRewindingEnabled without rewinding is answered by the executor: {} lost",
            lost_artifacts.by_digest.len()
        );
    }

    #[allow(clippy::too_many_arguments)]
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:341 ActionRewindStrategy.prepareRewindPlan
    fn prepare_rewind_plan(
        &self,
        seam: &dyn AnalysisSeam,
        failed_key: &SkyKey,
        failed_action: Option<(&ActionLookupData, &ActionRef)>,
        failed_key_deps: &IndexSet<SkyKey>,
        lost_inputs: &[ActionInputRef],
        owners: &Owners,
        env: &mut Environment<'_>,
        deps_to_rewind: &mut Vec<ActionRef>,
    ) -> Result<RewindPlanResult, ComputeError> {
        // This graph tracks which Skyframe nodes must be rewound and the dependency relationships
        // between them.
        let mut rewind_graph = Reset::new_rewind_graph_for(failed_key.clone());

        // An output of the failed action itself may have been lost after the action created it,
        // e.g. while it was downloaded. Rerunning the action, which rewinding does in any case
        // and without reusing cached results, recreates it unless the action propagates its
        // inputs without reading them, e.g. by symlinking to them: then the loss is really that
        // of its inputs, which are rewound below.
        let failed_action_key = failed_key.downcast::<ActionExecutionKey>().map(|k| &k.0);
        let lost_inputs_of_deps: Vec<ActionInputRef> = lost_inputs
            .iter()
            .filter(|lost_input| !failed_action_key.is_some_and(|k| is_output_of(k, lost_input)))
            .cloned()
            .collect();
        let lost_own_outputs = lost_inputs_of_deps.len() < lost_inputs.len();

        let lost_artifacts = self.get_lost_input_owning_direct_deps(
            failed_key,
            failed_key_deps,
            &lost_inputs_of_deps,
            owners,
        );

        // Additional nested sets we may need to invalidate that are the dependencies of an
        // insensitively propagating action, associated with the key that depends on them.
        let mut nested_sets_for_propagating_actions: IndexMap<SkyKey, IndexSet<SkyKey>> =
            IndexMap::new();

        let mut missing_dependencies = false;
        for lost_artifact in &lost_artifacts {
            let Some(action_map) = self.get_actions_for_lost_artifact(seam, lost_artifact, env)?
            else {
                // Some deps of the artifact are not done. If allowSkyframeRestarts() is false,
                // another rewind must be in-flight, and there is no need to rewind the shared deps
                // twice.
                missing_dependencies = true;
                continue;
            };
            let newly_visited_actions = add_artifact_deps_and_get_newly_visited_actions(
                &mut rewind_graph,
                lost_artifact,
                &action_map,
            );

            // Note that Artifact.key(lostArtifact) must be rewound. We do this after
            // addArtifactDepsAndGetNewlyVisitedActions so that it can track if actions are
            // already known to be in the graph. It is possible that the Artifact.key() is not
            // actually a direct dep of the action if it is below an ArtifactNestedSetKey, but this
            // edge is benign since it's always a transitive dep.
            rewind_graph.put_edge(failed_key.clone(), artifact_key(lost_artifact));
            deps_to_rewind.extend(
                newly_visited_actions
                    .iter()
                    .map(|a| a.action_analysis_metadata().clone()),
            );
            if self.check_actions(
                seam,
                &newly_visited_actions,
                env,
                &mut rewind_graph,
                deps_to_rewind,
                &mut nested_sets_for_propagating_actions,
            )? == CheckActionsStatus::MissingDependencies
            {
                missing_dependencies = true;
            }
        }

        if lost_own_outputs && let Some((failed_lookup_data, failed_action)) = failed_action {
            if self.check_actions(
                seam,
                &[ActionAndLookupDataOrTemplate::ActionAndLookupData(
                    failed_lookup_data.clone(),
                    failed_action.clone(),
                )],
                env,
                &mut rewind_graph,
                deps_to_rewind,
                &mut nested_sets_for_propagating_actions,
            )? == CheckActionsStatus::MissingDependencies
            {
                missing_dependencies = true;
            }
        }

        // The default behavior, when allowSkyframeRestarts() is false, ignores missing
        // dependencies.
        let _ = missing_dependencies;

        // addNestedSetPathsToRewindGraph, called after this loop, stops its walk when it finds a
        // node that is already in the rewind graph. However, because this rewinds all NestedSet
        // chains from a given root, early termination later on won't matter because all dependent
        // NestedSets are already in the graph. This may seem excessive, but it is not expected
        // that many NestedSets are actually involved in this walk, and that this only happens
        // rarely.
        for (root_key, nested_set_keys) in &nested_sets_for_propagating_actions {
            for nested_set_key in nested_set_keys {
                add_nested_set_chains_to_rewind_graph(&mut rewind_graph, nested_set_key);
                rewind_graph.put_edge(root_key.clone(), nested_set_key.clone());
            }
        }

        // This needs to be done after the loop above because
        // addArtifactDepsAndGetNewlyVisitedActions short-circuits when a node is already in the
        // rewind graph.
        add_nested_set_paths_to_rewind_graph(
            &mut rewind_graph,
            failed_key,
            failed_key_deps,
            &lost_artifacts,
        );

        Ok(RewindPlanResult {
            reset: Some(Reset::of(rewind_graph)),
        })
    }

    /// Creates a [`Reset`] to recover from undone indirect inputs that are unavailable due to
    /// unsuccessful rewinding.
    ///
    /// Used when an indirect dependency `Artifact.key` was rewound and completed with an error,
    /// but intermediate nested set nodes were never rewound, resulting in an inconsistent state
    /// where successful nodes depend on a node in error.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:476 ActionRewindStrategy.patchNestedSetGraphToPropagateError
    pub fn patch_nested_set_graph_to_propagate_error(
        &self,
        executor: &SkyframeActionExecutor,
        failed_key: &ActionLookupData,
        failed_action: &ActionRef,
        undone_inputs: &IndexSet<Artifact>,
        failed_action_deps: &IndexSet<SkyKey>,
    ) -> Reset {
        check_state!(
            executor.rewinding_enabled(),
            "Unexpected undone inputs: {:?}",
            undone_inputs
        );
        let failed_sky_key = SkyKey::new(ActionExecutionKey(failed_key.clone()));
        let mut rewind_graph = Reset::new_rewind_graph_for(failed_sky_key.clone());
        let undone: Vec<Artifact> = undone_inputs.iter().cloned().collect();
        add_nested_set_paths_to_rewind_graph(
            &mut rewind_graph,
            &failed_sky_key,
            failed_action_deps,
            &undone,
        );
        for input in undone_inputs {
            check_state!(
                rewind_graph.contains(&artifact_key(input)),
                "Cannot find input {} under any nested set deps of {}",
                input,
                failed_key
            );
        }

        // An undone input may be observed either during input checking (before attempting action
        // execution) or during lost input handling (after attempting action execution). In the
        // latter case, it is necessary to obsolete the ActionExecutionState so that after
        // rewinding, we will check inputs again and discover the propagated exception. This call
        // is a no-op in the former case, since there is no ActionExecutionState to obsolete.
        executor.prepare_for_rewinding(
            failed_key,
            failed_action,
            /* deps_to_rewind= */ &[],
            /* lost_own_outputs= */ false,
        );

        Reset::of(rewind_graph)
    }

    /// Logs the first N action rewind events and clears the history of failed actions' lost
    /// inputs and rewind plans.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:510 ActionRewindStrategy.reset
    pub fn reset(&self, executor: &SkyframeActionExecutor, event_handler: &dyn ExtendedEventHandler) {
        let rewinding_stats = PostableActionRewindingStats {
            lost_inputs_count: self.lost_inputs_count.swap(0, Ordering::SeqCst),
            lost_outputs_count: self.lost_outputs_count.swap(0, Ordering::SeqCst),
            rewound_action_count: executor.get_rewound_action_count(),
            same_action_lost_inputs_count: self
                .same_action_lost_inputs_count
                .swap(0, Ordering::SeqCst),
            same_top_level_key_lost_outputs_count: self
                .same_top_level_key_lost_outputs_count
                .swap(0, Ordering::SeqCst),
            action_rewind_events: self.rewind_event_samples.lock().clone(),
        };
        event_handler.post(Arc::new(rewinding_stats));
        self.current_build_lost_input_records.lock().clear();
        self.rewind_event_samples.lock().clear();
        self.rewind_event_sample_counter.store(0, Ordering::SeqCst);
    }

    /// Checks if the action identified by `failed_key` has lost any of the inputs in
    /// `current_attempt_lost_input_records` too many times.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:575 ActionRewindStrategy.checkIfActionLostInputTooManyTimes
    fn check_if_action_lost_input_too_many_times(
        &self,
        executor: &SkyframeActionExecutor,
        failed_key: &ActionLookupData,
        failed_action: &ActionRef,
        current_attempt_lost_input_records: &[LostInputRecord],
        lost_inputs_by_digest: &LostArtifacts,
    ) -> Result<(), ActionRewindException> {
        self.lost_inputs_count
            .fetch_add(current_attempt_lost_input_records.len(), Ordering::SeqCst);

        let mut records = self.current_build_lost_input_records.lock();
        let history_for_this_action = records
            .entry(SkyKey::new(ActionExecutionKey(failed_key.clone())))
            .or_default();
        if !history_for_this_action.is_empty() {
            self.same_action_lost_inputs_count
                .fetch_add(1, Ordering::SeqCst);
        }

        for lost_input_record in current_attempt_lost_input_records {
            // The same action losing the same input more than once is unexpected [*]. The action
            // should have waited until the depended-on action which generates the lost input is
            // (re)run before trying again.
            //
            // [*], TODO(b/123993876): To mitigate a race condition (believed to be) caused by
            // non-topological Skyframe dirtying of depended-on nodes, this check fails the build
            // only if the same input is repeatedly lost.
            let digest = &lost_input_record.lost_input_digest;
            let count = history_for_this_action
                .entry(lost_input_record.clone())
                .or_insert(0);
            *count += 1;
            let losses = *count;
            if losses > MAX_REPEATED_LOST_INPUTS {
                drop(records);
                // This ensures coalesced shared actions aren't orphaned.
                executor.prepare_for_rewinding(
                    failed_key,
                    failed_action,
                    /* deps_to_rewind= */ &[],
                    /* lost_own_outputs= */ false,
                );
                let lost_input = lost_inputs_by_digest
                    .by_digest
                    .get(digest)
                    .and_then(|inputs| {
                        inputs.iter().find(|lost| {
                            lost.get_exec_path_string() == lost_input_record.lost_input_path
                        })
                    })
                    .expect("Iterables.find: the record's input");
                // Java: String.format("...failedAction: %.10000s", failedAction).
                let failed_action_string: String =
                    failed_action.to_string_java().chars().take(10000).collect();
                let message = format!(
                    "lost input too many times (#{}) for the same action. lostInput: {}, \
                     lostInput digest: {}, failedAction: {}",
                    losses,
                    action_input_to_string(lost_input),
                    digest,
                    failed_action_string
                );
                // PORT: bugReporter.sendBugReport(e) is not ported (BugReport).
                return Err(ActionRewindException::generic(
                    message,
                    Code::LostInputTooManyTimes,
                ));
            }
            // PORT: skipped, logging ("lost input again (#%s) for the same action").
        }
        Ok(())
    }

    /// Calculates the aggregation artifacts (tree artifacts, filesets, runfiles) that own
    /// `lost_inputs` — see [`calculate_lost_input_owners`].
    ///
    /// Not all input artifacts' keys are direct deps - they may be below an
    /// ArtifactNestedSetKey. Expand all ArtifactNestedSetKey deps to get a flat set with all input
    /// artifact keys.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:687 ActionRewindStrategy.getLostInputOwningDirectDeps
    fn get_lost_input_owning_direct_deps(
        &self,
        failed_key: &SkyKey,
        failed_key_deps: &IndexSet<SkyKey>,
        lost_inputs: &[ActionInputRef],
        owners: &Owners,
    ) -> Vec<Artifact> {
        let mut expanded_deps: HashSet<SkyKey> = HashSet::new();
        for dep in failed_key_deps {
            if let Some(nested_set_dep) = dep.downcast::<ArtifactNestedSetKey>() {
                expanded_deps.extend(nested_set_dep.0.to_list().iter().map(artifact_key));
            } else {
                expanded_deps.insert(dep.clone());
            }
        }

        // Java: a HashSet<DerivedArtifact>.
        let mut lost_input_owning_direct_deps: IndexSet<Artifact> = IndexSet::new();
        for lost_input in lost_inputs {
            let mut found_lost_input_dep_owner = false;

            let direct_owners = owners.get(lost_input);
            for direct_owner in &direct_owners {
                check_derived(direct_owner);

                // Rewinding must invalidate all Skyframe paths from the failed action to the
                // action which generates the lost input. Intermediate nodes not on the shortest
                // path to that action may have values that depend on the output of that action.
                // If these intermediate nodes are not invalidated, then their values may become
                // stale. Therefore, this method collects not only the first action dep associated
                // with the lost input, but all of them.

                let transitive_owners =
                    owners.get(&blaze_exec::actions::action_adapters::artifact_input(direct_owner));
                for transitive_owner in &transitive_owners {
                    check_derived(transitive_owner);

                    if expanded_deps.contains(&artifact_key(transitive_owner)) {
                        // The lost input is included in an aggregation artifact (e.g. a tree
                        // artifact or fileset) that is included by an aggregation artifact (e.g. a
                        // runfiles tree) that the action directly depends on.
                        lost_input_owning_direct_deps.insert(transitive_owner.clone());
                        found_lost_input_dep_owner = true;
                    }
                }

                if expanded_deps.contains(&artifact_key(direct_owner)) {
                    // The lost input is included in an aggregation artifact (e.g. a tree
                    // artifact, fileset, or runfiles tree) that the action directly depends on.
                    lost_input_owning_direct_deps.insert(direct_owner.clone());
                    found_lost_input_dep_owner = true;
                }
            }

            if let Some(artifact) = as_blaze_artifact(lost_input)
                && expanded_deps.contains(&artifact_key(artifact))
            {
                check_derived(artifact);

                lost_input_owning_direct_deps.insert(artifact.clone());
                found_lost_input_dep_owner = true;
            }

            if !found_lost_input_dep_owner {
                // Rewinding can't do anything about a lost input that can't be associated with a
                // direct dep of the failed action. In this case, try resetting the failed action
                // (and no other deps) just in case that helps. If it does not help, then
                // eventually the action will fail in checkIfActionLostInputTooManyTimes.
                // PORT: bugReporter.sendNonFatalBugReport is not ported (BugReport): "Lost input
                // not a dep of the failed action and can't be associated with such a dep.
                // lostInput: %s, owners: %s, failedKey: %s".
                let _ = (failed_key, owners);
            }
        }
        lost_input_owning_direct_deps.into_iter().collect()
    }

    /// Looks at each action in `actions_to_check` and determines whether additional artifacts or
    /// actions need to be rewound. If this finds more actions to rewind, those actions are
    /// recursively checked too.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:792 ActionRewindStrategy.checkActions
    fn check_actions(
        &self,
        seam: &dyn AnalysisSeam,
        actions_to_check: &[ActionAndLookupDataOrTemplate],
        env: &mut Environment<'_>,
        rewind_graph: &mut RewindGraph,
        deps_to_rewind: &mut Vec<ActionRef>,
        nested_set_deps: &mut IndexMap<SkyKey, IndexSet<SkyKey>>,
    ) -> Result<CheckActionsStatus, ComputeError> {
        let mut missing_dependencies = false;
        let mut unchecked_actions: VecDeque<(ActionLookupData, ActionRef)> = VecDeque::new();
        filter_action_and_lookup_data_to(actions_to_check, &mut unchecked_actions);
        while let Some((action_key, action)) = unchecked_actions.pop_front() {
            let mut artifacts_to_check: Vec<Artifact> = vec![];
            let mut newly_discovered_actions: Vec<ActionLookupData> = vec![];

            if may_insensitively_propagate_inputs(action.as_ref()) {
                // Rewinding this action won't recreate the missing input. We need to also rewind
                // this action's non-source inputs and the actions which created those inputs.
                self.add_propagating_action_deps_and_get_newly_visited_artifacts_and_actions(
                    rewind_graph,
                    &action_key,
                    &action,
                    &mut artifacts_to_check,
                    &mut newly_discovered_actions,
                    nested_set_deps,
                );
            }

            for action_lookup_data in newly_discovered_actions {
                let Some(additional_action) =
                    crate::action_execution_function::get_action_for_lookup_data(
                        seam,
                        env,
                        &action_lookup_data,
                    )?
                else {
                    missing_dependencies = true;
                    continue;
                };
                deps_to_rewind.push(additional_action.clone());
                unchecked_actions.push_back((action_lookup_data, additional_action));
            }
            for artifact in &artifacts_to_check {
                let Some(action_map) = self.get_actions_for_lost_artifact(seam, artifact, env)?
                else {
                    missing_dependencies = true;
                    continue;
                };
                let newly_visited_actions =
                    add_artifact_deps_and_get_newly_visited_actions(rewind_graph, artifact, &action_map);
                deps_to_rewind.extend(
                    newly_visited_actions
                        .iter()
                        .map(|a| a.action_analysis_metadata().clone()),
                );
                filter_action_and_lookup_data_to(&newly_visited_actions, &mut unchecked_actions);
            }
        }
        Ok(if missing_dependencies {
            CheckActionsStatus::MissingDependencies
        } else {
            CheckActionsStatus::Success
        })
    }

    /// For a propagating `action` with key `action_key`, add its generated inputs' keys to
    /// `rewind_graph`, add edges from `action_key` to those keys, add any artifacts to
    /// `newly_visited_artifacts`, and add any `ActionLookupData`s to `newly_visited_actions`.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:860 ActionRewindStrategy.addPropagatingActionDepsAndGetNewlyVisitedArtifactsAndActions
    fn add_propagating_action_deps_and_get_newly_visited_artifacts_and_actions(
        &self,
        rewind_graph: &mut RewindGraph,
        action_key: &ActionLookupData,
        action: &ActionRef,
        newly_visited_artifacts: &mut Vec<Artifact>,
        newly_visited_actions: &mut Vec<ActionLookupData>,
        nested_set_deps: &mut IndexMap<SkyKey, IndexSet<SkyKey>>,
    ) {
        let action_sky_key = SkyKey::new(ActionExecutionKey(action_key.clone()));
        for input in action.get_inputs().to_list().iter() {
            if input.is_source_artifact() {
                continue;
            }
            let artifact_sky_key = artifact_key(input);
            // Rewinding all derived inputs of propagating actions is overkill. Preferably, we'd
            // want to only rewind the inputs which correspond to the known lost outputs. The
            // information to do this is probably present in the data available to
            // #prepareRewindPlan.
            //
            // Rewinding is expected to be rare, so refining this may not be necessary.
            let newly_visited = rewind_graph.add_node(artifact_sky_key.clone());
            if newly_visited {
                if let Some(artifact) = artifact_sky_key.downcast::<ArtifactKey>() {
                    newly_visited_artifacts.push(artifact.0.clone());
                } else if let Some(action_lookup_data) =
                    artifact_sky_key.downcast::<ActionExecutionKey>()
                {
                    newly_visited_actions.push(action_lookup_data.0.clone());
                }
            }
            rewind_graph.put_edge(action_sky_key.clone(), artifact_sky_key);
        }

        // Record the action's NestedSet inputs as dependencies to be rewound.
        for nested_set in action.get_inputs().get_non_leaves() {
            nested_set_deps
                .entry(action_sky_key.clone())
                .or_default()
                .insert(SkyKey::new(ArtifactNestedSetKey::create(nested_set)));
        }

        // Rewinding ignores artifacts returned by Action#getAllowedDerivedInputs because:
        // 1) the set of actions with non-throwing implementations of getAllowedDerivedInputs,
        // 2) the set of actions that "mayInsensitivelyPropagateInputs",
        // should have no overlap.
        // PORT: bugReporter.sendBugReport for an action that also discovers inputs ("Action
        // insensitively propagates and discovers inputs") is not ported (BugReport); the
        // propagating actions here (symlinks, runfiles trees) never discover inputs.
    }

    /// Returns the map of `lost_input`'s execution-phase dependencies (i.e. generating actions),
    /// keyed by their `ActionLookupData` keys, or `None` if any of those dependencies are not
    /// done.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:950 ActionRewindStrategy.getActionsForLostArtifact
    fn get_actions_for_lost_artifact(
        &self,
        seam: &dyn AnalysisSeam,
        lost_input: &Artifact,
        env: &mut Environment<'_>,
    ) -> Result<Option<IndexMap<ActionLookupData, ActionRef>>, ComputeError> {
        let Some(action_execution_deps) = self.get_action_execution_deps(seam, lost_input, env)?
        else {
            return Ok(None);
        };

        let mut actions: IndexMap<ActionLookupData, ActionRef> = IndexMap::new();
        let mut missing_action = false;
        for dep in action_execution_deps {
            let Some(action_analysis_metadata) = self.get_action_analysis_metadata(seam, env, &dep)?
            else {
                missing_action = true;
                continue;
            };
            actions.insert(dep, action_analysis_metadata);
        }
        if missing_action {
            return Ok(None);
        }
        Ok(Some(actions))
    }

    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:974 ActionRewindStrategy.getActionAnalysisMetadata
    fn get_action_analysis_metadata(
        &self,
        seam: &dyn AnalysisSeam,
        env: &mut Environment<'_>,
        action_lookup_data: &ActionLookupData,
    ) -> Result<Option<ActionRef>, ComputeError> {
        let Some(action_lookup_value) = get_action_lookup_value(
            action_lookup_data.get_action_lookup_key(),
            seam,
            env,
            /* crash_if_action_owner_missing= */ !allow_skyframe_restarts(),
        )?
        else {
            return Ok(None);
        };
        Ok(Some(
            action_lookup_value.get_actions()[action_lookup_data.get_action_index() as usize].clone(),
        ))
    }

    /// Returns the set of `lost_input`'s execution-phase dependencies (i.e. generating actions),
    /// or `None` if any of those dependencies are not done.
    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:992 ActionRewindStrategy.getActionExecutionDeps
    fn get_action_execution_deps(
        &self,
        seam: &dyn AnalysisSeam,
        lost_input: &Artifact,
        env: &mut Environment<'_>,
    ) -> Result<Option<IndexSet<ActionLookupData>>, ComputeError> {
        if !lost_input.is_tree_artifact() {
            return Ok(Some(IndexSet::from([lost_input
                .get_generating_action_key()
                .clone()])));
        }
        let Some(artifact_dependencies) = ArtifactDependencies::discover_dependencies(
            lost_input,
            seam,
            env,
            /* crash_if_action_owner_missing= */ !allow_skyframe_restarts(),
        )?
        else {
            return Ok(None);
        };

        if !artifact_dependencies.is_template_action_for_tree_artifact() {
            return Ok(Some(IndexSet::from([lost_input
                .get_generating_action_key()
                .clone()])));
        }

        // This ignores the ActionTemplateExpansionKey dependency of the template artifact because
        // we expect to never need to rewind that.
        let Some(action_template_expansion_keys) =
            artifact_dependencies.get_action_template_expansion_keys(env)?
        else {
            return Ok(None);
        };
        let mut result = IndexSet::new();
        result.insert(lost_input.get_generating_action_key().clone());
        result.extend(action_template_expansion_keys);
        Ok(Some(result))
    }

    // Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1022 ActionRewindStrategy.shouldRecordRewindEventSample
    fn should_record_rewind_event_sample(&self) -> bool {
        self.rewind_event_sample_counter
            .fetch_add(1, Ordering::SeqCst)
            < MAX_ACTION_REWIND_EVENTS
    }
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1026 ActionRewindStrategy.allowSkyframeRestarts
fn allow_skyframe_restarts() -> bool {
    // cachingDependenciesSupplier.get().isRetrievalEnabled(): remote analysis caching (not
    // ported; Bazel's default provider has retrieval disabled).
    false
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:650 ActionRewindStrategy.createLostInputRecords
fn create_lost_input_records(lost_inputs_by_digest: &LostArtifacts) -> Vec<LostInputRecord> {
    lost_inputs_by_digest
        .entries()
        .into_iter()
        .map(|(digest, input)| LostInputRecord {
            lost_input_digest: digest.to_owned(),
            lost_input_path: input.get_exec_path_string(),
        })
        .collect()
}

/// Calculates the aggregation artifacts (tree artifacts, filesets, runfiles) that own
/// `lost_inputs`.
///
/// PORT: Java's `inputArtifactData.getFilesets()` is empty here: the action input map holds no
/// filesets (`ActionInputMapValue` has no fileset variant), and runfiles values hold no
/// filesets either.
// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:660 ActionRewindStrategy.calculateLostInputOwners
fn calculate_lost_input_owners(
    lost_inputs: &[ActionInputRef],
    input_artifact_data: &ActionInputMetadata,
) -> Owners {
    let mut lost_inputs_and_owners: HashSet<ActionInputRef> = HashSet::new();
    let mut owners = Owners::default();
    for lost_input in lost_inputs {
        lost_inputs_and_owners.insert(lost_input.clone());
        if let Some(artifact) = as_blaze_artifact(lost_input)
            && artifact.has_parent()
        {
            let parent = artifact.get_parent().expect("hasParent").clone();
            lost_inputs_and_owners.insert(blaze_exec::actions::action_adapters::artifact_input(
                &parent,
            ));
            owners.put(lost_input.clone(), parent);
        }
    }

    // Runfiles trees may contain tree artifacts and filesets, but not vice versa. Runfiles are
    // processed last to ensure that any lost input owning tree artifacts and filesets are already
    // in lostInputsAndOwners.
    for (runfiles_input, runfiles_value) in input_artifact_data.get_runfiles_trees() {
        let runfiles_artifact = as_blaze_artifact(&runfiles_input)
            .expect("(Artifact) inputArtifactData.getInput(runfilesTree.getExecPath())")
            .clone();
        check_state!(
            runfiles_artifact.is_runfiles_tree(),
            "{}",
            runfiles_artifact
        );

        // RunfilesArtifactValue.getAllArtifacts(): files, then trees (no filesets, see above).
        let mut all_artifacts: Vec<ActionInputRef> = vec![];
        runfiles_value.for_each_file(|file, _| all_artifacts.push(file.clone()));
        runfiles_value.for_each_tree(|tree, _| all_artifacts.push(tree.clone()));
        for artifact in all_artifacts {
            if lost_inputs_and_owners.contains(&artifact) {
                owners.put(artifact, runfiles_artifact.clone());
            }
        }
    }

    owners
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:770 ActionRewindStrategy.checkDerived
fn check_derived(artifact: &Artifact) {
    check_state!(
        !artifact.is_source_artifact(),
        "Unexpected source artifact: {}",
        artifact
    );
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:774 ActionRewindStrategy.isOutputOf
fn is_output_of(action_key: &ActionLookupData, input: &ActionInputRef) -> bool {
    as_blaze_artifact(input).is_some_and(|artifact| {
        !artifact.is_source_artifact()
            && artifact.has_known_generating_action()
            && artifact.get_generating_action_key() == action_key
    })
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:843 ActionRewindStrategy.filterActionAndLookupDataTo
fn filter_action_and_lookup_data_to(
    actions: &[ActionAndLookupDataOrTemplate],
    queue: &mut VecDeque<(ActionLookupData, ActionRef)>,
) {
    for action in actions {
        match action {
            ActionAndLookupDataOrTemplate::ActionAndLookupData(lookup_data, action) => {
                queue.push_back((lookup_data.clone(), action.clone()))
            }
            ActionAndLookupDataOrTemplate::TemplateWrapper(_) => {}
        }
    }
}

/// For an artifact `artifact` with generating actions (and their associated `ActionLookupData`)
/// `action_map`, add those actions' keys to `rewind_graph` and add edges from `artifact` to
/// those keys.
///
/// Returns a list of key+action pairs for each action whose key was newly added to the graph.
// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:917 ActionRewindStrategy.addArtifactDepsAndGetNewlyVisitedActions
fn add_artifact_deps_and_get_newly_visited_actions(
    rewind_graph: &mut RewindGraph,
    artifact: &Artifact,
    action_map: &IndexMap<ActionLookupData, ActionRef>,
) -> Vec<ActionAndLookupDataOrTemplate> {
    let mut newly_visited_actions = Vec::with_capacity(action_map.len());
    let artifact_sky_key = artifact_key(artifact);
    for (action_key, action) in action_map {
        let action_sky_key = SkyKey::new(ActionExecutionKey(action_key.clone()));
        if rewind_graph.add_node(action_sky_key.clone()) {
            newly_visited_actions.push(if as_action_template(action.as_ref()).is_some() {
                ActionAndLookupDataOrTemplate::TemplateWrapper(action.clone())
            } else {
                ActionAndLookupDataOrTemplate::ActionAndLookupData(
                    action_key.clone(),
                    action.clone(),
                )
            });
        }
        if artifact_sky_key != action_sky_key {
            rewind_graph.put_edge(artifact_sky_key.clone(), action_sky_key);
        }
    }
    newly_visited_actions
}

/// `action.mayInsensitivelyPropagateInputs()`: true for the actions that override it
/// (`SymlinkAction`, `SymlinkTreeAction`, `RunfilesTreeAction`, `SolibSymlinkAction`), false
/// otherwise (`ActionExecutionMetadata`'s default).
// Java: com/google/devtools/build/lib/actions/ActionExecutionMetadata.java:95 ActionExecutionMetadata.mayInsensitivelyPropagateInputs
fn may_insensitively_propagate_inputs(action: &dyn Action) -> bool {
    let any = action.as_any();
    if let Some(a) = any.downcast_ref::<blaze_actions::analysis::actions::symlink_action::SymlinkAction>() {
        return a.may_insensitively_propagate_inputs();
    }
    if let Some(a) =
        any.downcast_ref::<blaze_actions::analysis::actions::symlink_tree_action::SymlinkTreeAction>()
    {
        return a.may_insensitively_propagate_inputs();
    }
    if let Some(a) = any.downcast_ref::<blaze_actions::actions::runfiles_tree_action::RunfilesTreeAction>()
    {
        return a.may_insensitively_propagate_inputs();
    }
    if let Some(a) = any.downcast_ref::<blaze_actions::rules::cpp::solib_symlink_action::SolibSymlinkAction>()
    {
        return a.may_insensitively_propagate_inputs();
    }
    false
}

/// Augments the given rewind graph with all chains of `ArtifactNestedSetKey` nodes reachable
/// from `key` and non source artifacts in them.
///
/// The walk is terminated when a node is already in the rewind graph.
///
/// PORT: Java walks the set's children in their stored order (leaves and non-leaves mixed);
/// here the leaves come first, then the non-leaves (`NestedSet::get_leaves` /
/// `get_non_leaves`). Only the insertion order of the rewind graph differs.
// Java: com/google/devtools/build/lib/collect/nestedset/ArtifactNestedSetKey.java:115 ArtifactNestedSetKey.addNestedSetChainsToRewindGraph
fn add_nested_set_chains_to_rewind_graph(rewind_graph: &mut RewindGraph, key: &SkyKey) {
    if rewind_graph.contains(key) {
        return;
    }
    let nested_set = &key
        .downcast::<ArtifactNestedSetKey>()
        .expect("an ArtifactNestedSetKey")
        .0;
    for artifact in nested_set.get_leaves() {
        if !artifact.is_source_artifact() {
            rewind_graph.put_edge(key.clone(), artifact_key(&artifact));
        }
    }
    for child in nested_set.get_non_leaves() {
        let next_node = SkyKey::new(ArtifactNestedSetKey::create(child));
        add_nested_set_chains_to_rewind_graph(rewind_graph, &next_node);
        rewind_graph.put_edge(key.clone(), next_node);
    }
}

/// Augments the given rewind graph with paths from `failed_key` to `lost_artifacts`
/// discoverable by following the `ArtifactNestedSetKey` nodes in `failed_key_deps`.
///
/// `rewind_graph` must not contain any `ArtifactNestedSetKey` nodes prior to calling this
/// method.
// Java: com/google/devtools/build/lib/collect/nestedset/ArtifactNestedSetKey.java:140 ArtifactNestedSetKey.addNestedSetPathsToRewindGraph
fn add_nested_set_paths_to_rewind_graph(
    rewind_graph: &mut RewindGraph,
    failed_key: &SkyKey,
    failed_key_deps: &IndexSet<SkyKey>,
    lost_artifacts: &[Artifact],
) {
    let lost: HashSet<&Artifact> = lost_artifacts.iter().collect();
    let mut seen: HashSet<SkyKey> = HashSet::new();
    for nested_set_dep in failed_key_deps
        .iter()
        .filter(|k| k.downcast::<ArtifactNestedSetKey>().is_some())
    {
        if search_for_lost_artifacts(nested_set_dep, rewind_graph, &lost, &mut seen) {
            rewind_graph.put_edge(failed_key.clone(), nested_set_dep.clone());
        }
    }
}

// Java: com/google/devtools/build/lib/collect/nestedset/ArtifactNestedSetKey.java:152 ArtifactNestedSetKey.searchForLostArtifacts
fn search_for_lost_artifacts(
    node: &SkyKey,
    rewind_graph: &mut RewindGraph,
    lost_artifacts: &HashSet<&Artifact>,
    seen: &mut HashSet<SkyKey>,
) -> bool {
    if rewind_graph.contains(node) {
        return true;
    }
    if !seen.insert(node.clone()) {
        return false;
    }
    let nested_set = node
        .downcast::<ArtifactNestedSetKey>()
        .expect("an ArtifactNestedSetKey")
        .0
        .clone();
    let mut any_found = false;
    for artifact in nested_set.get_leaves() {
        if lost_artifacts.contains(&artifact) {
            rewind_graph.put_edge(node.clone(), artifact_key(&artifact));
            any_found = true;
        }
    }
    for child in nested_set.get_non_leaves() {
        let next_node = SkyKey::new(ArtifactNestedSetKey::create(child));
        if search_for_lost_artifacts(&next_node, rewind_graph, lost_artifacts, seen) {
            rewind_graph.put_edge(node.clone(), next_node);
            any_found = true;
        }
    }
    any_found
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1040 ActionRewindStrategy.createLostInputRewindEvent
fn create_lost_input_rewind_event(
    failed_action: &ActionRef,
    rewind_plan: &Reset,
    lost_input_records: &[LostInputRecord],
) -> ActionRewindEvent {
    let mut event = create_rewind_event_builder(rewind_plan, lost_input_records);
    event.action_description = Some(ActionDescription {
        r#type: failed_action.get_mnemonic().to_string(),
        rule_label: failed_action
            .get_owner()
            .get_label()
            .map(|l| l.to_string())
            .unwrap_or_else(|| panic!("NullPointerException: getOwner().getLabel()")),
    });
    event
}

// Java: com/google/devtools/build/lib/skyframe/rewinding/ActionRewindStrategy.java:1050 ActionRewindStrategy.createRewindEventBuilder
fn create_rewind_event_builder(
    rewind_plan: &Reset,
    lost_input_records: &[LostInputRecord],
) -> ActionRewindEvent {
    ActionRewindEvent {
        action_description: None,
        top_level_action_lookup_key_description: None,
        lost_inputs: lost_input_records
            .iter()
            .take(MAX_LOST_INPUTS_RECORDED)
            .map(|lost_input_record| LostInput {
                path: lost_input_record.lost_input_path.clone(),
                digest: lost_input_record.lost_input_digest.clone(),
            })
            .collect(),
        total_lost_inputs_count: lost_input_records.len() as i32,
        invalidated_nodes_count: rewind_plan.rewind_graph().node_count() as i32,
    }
}
